\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 1r\endash 19v}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Clavicula Salomonis expurgata oder Schl\u252 \'fcssel des K\u246 \'f6nigs Salomons wunderbahrlicher Geheimnisse und vieler zuk\u252 \'fcnfftigen Dinge}}\plain \f1\b\i\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1r) Titelblatt, \plain \f1\i\lang1033\fs24 Clavicula Salomonis expurgata oder Schl\u252 \'fcssel des K\u246 \'f6nigs Salamon \u8230 \'85 >J. H. H.< Anno 1752.\plain \f1\lang1033\fs24  \endash  1v leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (2r\endash 19v) Text, Inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Der K\u246 \'f6nig Salomon spricht zu seinem Sohn Roboam, wi\u223 \'dfe mein Sohn}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \endash   \plain \f1\i\lang1033\fs24 \u8230 \'85 und im Hebr\u228 \'e4ischen Text, ist Jehovah geschrieben. Nun sey Gott gelobet in allen, seinen Wundern, und Wercken, ohne End\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 in alle Ewigkeit, die hochgelobte Dreyfaltigkeit Gottvater, Sohn und heiliger Geist. Amen. Amen. Amen. Fiat. Fiat. Fiat. Amen.\plain \f1\lang1033\fs24  19v leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 [20r/v] und IIr/v leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

