\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Pappband wohl {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 vor 1710}}\plain \f1\lang1033\fs20  mit \u220 \'dcberzug aus marmoriertem Buntpapier (breiter Kamm, in Wellen gezogen, dar\u252 \'fcber ganzseitige Spirale, viele Aussprengungen. Farben: rot, blau, wei\u223 \'df, gr\u252 \'fcn, gelb). R\u252 \'fccken und Ecken des Vorder- und Hinterdeckels mit Pergament\u252 \'fcberzug. Handschriften, die in dieses oder \u228 \'e4hnliches Buntpapier gebunden sind: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. mag. 2}}\plain \f1\lang1033\fs20 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Schnitt blau gef\u228 \'e4rbt.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Courier New;}{\f3\fnil\fcharset2 Wingdings;}{\f4\fnil\fcharset2 Symbol;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}{\*\listtable{\list\listtemplateid1889170811
{\listlevel\levelnfc23\leveljc0\li720\fi-360\jclisttab\tx0{\leveltext\'01\'96;}{\levelnumbers;}\f1\fs20\lang1033}
