\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls25\ilvl0 {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  Zeichnungen}}\plain \f1\lang1033\fs20  auf 1r und 9r
\plain\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
