\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Zustand:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls3\ilvl0 \plain \f1\lang1033\fs20  Einband leicht fleckig
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls3\ilvl0 \plain \f1\lang1033\fs20  Buchblock leicht fleckig
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls3\ilvl0 \plain \f1\lang1033\fs20  Buchblock leicht gewellt
