\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Zustand:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f4\fs20\lang1024 \u-4051 ?\tab}\ls12\ilvl0 \plain \f1\lang1033\fs20 Einband fleckig, u. a. Feuchtigkeitsfleck
\plain\par {\listtext\pard\plain\f4\fs20\lang1024 \u-4051 ?\tab}\ls12\ilvl0 \plain \f1\lang1033\fs20 Ecken und R\u228 \'e4nder des Einbands geknickt und eingerissen 
\plain\par {\listtext\pard\plain\f4\fs20\lang1024 \u-4051 ?\tab}\ls12\ilvl0 \plain \f1\lang1033\fs20 Buchblock leicht fleckig
\plain\par {\listtext\pard\plain\f4\fs20\lang1024 \u-4051 ?\tab}\ls12\ilvl0 \plain \f1\lang1033\fs20 beginnender Tintenfra\u223 \'df (ohne Ausbr\u252 \'fcche)
\plain\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Foliierung:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f4\fs20\lang1024 \u-4051 ?\tab}\ls12\ilvl0 \plain \f1\lang1033\fs20 Bleistiftfoliierung \plain \f1\i\lang1033\fs20 1\endash 18 \plain \f1\lang1033\fs20 beginnend mit dem Titelblatt, wohl von {\field{\*\fldinst HYPERLINK "hida://bezper[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Robert Naumann}}\plain \f1\lang1033\fs20  im Zuge der Katalogisierung der Handschriften der Stadtbibliothek (1830er Jahre), s. u., Lit. (Naumann 1838).
\plain\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Wasserzeichen:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Buchblock: Wappen - Gemeine Figuren - Realien - Musikinstrumente - Horn (ohne Beizeichen Name) - ohne weitere Belegung - Krone (in WZIS diese Motivgruppe mit Belegen ab 1658, kein passender Beleg f\u252 \'fcr das Wasserzeichen in Cod. mag. 66). Da Papier mit diesem Wasserzeichen auch im Buchblock von Cod. mag. 66 begegnet, der aufgrund seines Wasserzeichens (Traube, s. u.) wiederum nach 1697 entstanden sein muss, ergibt sich als Terminus post quem f\u252 \'fcr diese Motivgruppe in Cod. mag. 66 ebenfalls 1697. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Dasselbe Wasserzeichen ebenso{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  im Vorsatz von Cod. mag. 8, Cod. mag. 30, Cod. mag. 50, Cod. mag. 69.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Buchstaben EN in gekr\u246 \'f6nter Tafel - mit angeh\u228 \'e4ngter Weintraube - quer zu den Stegen (ohne Klassifikation in WZIS). Ein solches Wasserzeichen f\u252 \'fcr den Papiermacher Ernst Neubert von der Papierm\u252 \'fchle Oberschlema (Wirkungszeit 1697\endash 1730) belegt.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Wasserzeichenklassifizierung und Beleginformation nach freundlicher Auskunft von Andrea Lothe, Deutsches Buch- und Schriftmuseum der Deutschen Nationalbibliothek Leipzig, Papierhistorische Sammlungen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Papier mit diesem Wasserzeichen wurde auch f\u252 \'fcr den Buchblock der Handschriften {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. mag. 19, Cod. mag. 30, Cod. mag. 40, Cod. mag. 50, Cod. mag. 54, Cod. mag. 55, Cod. mag. 56, Cod. mag. 60, Cod. mag. 69, Cod. mag. 78 und Cod. mag. 79 verwendet.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Schriftart:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ein Schreiber: {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kurrent}}\plain \f1\lang1033\fs20 . \u220 \'dcberschriften, Beschriftung der Siegel, Schemata und Zeichnungen sowie einzelne Textpassagen in lateinischer Schrift.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Derselbe Schreiber wie in {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. mag. 12, Cod. mag. 22, Cod. mag. 23, Cod. mag. 32, Cod. mag. 33, Cod. mag. 35, Cod. mag. 36, Cod. mag. 37, Cod. mag. 38, Cod. mag. 40, Cod. mag. 42, Cod. mag. 43, Cod. mag. 45, Cod. mag. 46, Cod. mag. 47, Cod. mag. 51, Cod. mag. 56, Cod. mag. 58, Cod. mag. 59, Cod. mag. 65, Cod. mag. 67, Cod. mag. 71, Cod. mag. 72, Cod. mag. 73, Cod. mag. 74, Cod. mag. 82, Cod. mag. 86, Cod. mag. 87, Cod. mag. 91, Cod. mag. 99, Cod. mag. 100, Cod. mag. 101, Cod. mag. 102, Cod. mag. 104, Cod. mag. 105, Cod. mag. 106, Cod. mag. 111, Cod. mag. 112, Cod. mag. 118, Cod. mag. 124, Cod. mag. 125, Cod. mag. 127, Cod. mag. 131, Cod. mag. 132, Cod. mag. 133, Cod. mag. 135 und Cod. mag. 140, der au\u223 \'dferdem Symbole in Cod. mag. 11, eine Beischrift eines Schemas in Cod. mag. 69 und eines Schemas in Cod. mag. 21 und Nachtr\u228 \'e4ge in Cod. mag. 78}}\plain \f1\lang1033\fs20  schrieb und als H1 auch einen Teil der Nummern-Eintr\u228 \'e4ge auf den Titelseiten der Handschriften vorgenommen hat (s. u., Geschichte).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Rubrizierung und Buchschmuck:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls11\ilvl0 \plain \f1\lang1033\fs20 Siegel, Schemata und Zeichnungen (u. a. eines Diebes auf 16v).
\plain\par \pard\fi0\li360\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Besonderheiten:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls13\ilvl0 \plain \f1\lang1033\fs20 Bl\u228 \'e4tter des Buchblocks nicht beschnitten.}

