\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1r\endash 44v:}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Praxis Cabalistica Astronomiae aureae solaris vel supernaturalis. Die guldene Wunder Kunst aller Heiligen oder Der guldene Schl\u252 \'fc\u223 \'dfel die himmlischen Portas oder Fenster des himmels zu er\u246 \'f6ffnen. Item wie die Bluhmen des Paradieses, und die Fr\u252 \'fcchte des guldenen Baumes zu brechen.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1r) Titelblatt, \plain \f1\i\lang1033\fs24 Praxis Cabalistica Astronomiae aureae solaris vel supernaturalis. Die guldene Wunder Kunst aller Heiligen oder Der guldene Schl\u252 \'fc\u223 \'dfel die himmlischen Portas oder Fenster des himmels zu er\u246 \'f6ffnen. Item wie die Bluhmen des Paradieses, und die Fr\u252 \'fcchte des guldenen Baumes zu brechen. Venite Videte ac gustate qvam suavis atque mirabilis sit Iehovah Dominus, Deus noster, omnibus in spiritu ac Veritate invocantibus eum. \plain \f1\lang1033\fs24 \endash \plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 1v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (2r\endash 44v) \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24 Practica Cabalistica Astronomiae supernaturalis vel Aureae solaris. Praxeos\plain \f1\lang1033\fs24  [durchgestrichen \plain \f1\i\lang1033\fs24 vel\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 totius huius summa. \plain \f1\lang1033\fs24 Text, Inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ante omnia oportet ac decet nos prius esse pielotos ac poenitentialiter purgatos \u8230 \'85}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 .}

