\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Ir\endash Iv: leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1r\endash 21r}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Alberti Magni CABALA NIGRA da\u223 \'df ist Acht gro\u223 \'dfer Welt Geister Beschwerungen, Nestorats zur Liebe, Paymon zur Unsichtbarkeit, Waran zum Sch\u228 \'e4tzen, Qziel verborgene Dinge zu offenbahren, auch der Menschen Gedancken, Pergo alles lebendige zu t\u246 \'f6ten, Mephistophilis Wei\u223 \'dfheit und gro\u223 \'dfen Verstand zu wege zu bringen, Rago alles zu vergifften, Megog B\u228 \'e4ume, Bluhmen, und Kr\u228 \'e4uter, V\u246 \'f6gel, Regen und Schnee zu wege zu bringen.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1r) Titelblatt, \plain \f1\i\lang1033\fs24 Alberti Magni CABALA NIGRA da\u223 \'df ist Acht gro\u223 \'dfer Welt Geister Beschwerungen, Nestorats zur Liebe, Paymon zur Unsichtbarkeit, Waran zum Sch\u228 \'e4tzen, Qziel verborgene Dinge zu offenbahren, auch der Menschen Gedancken, Pergo alles lebendige zu t\u246 \'f6ten, Mephistophilis Wei\u223 \'dfheit und gro\u223 \'dfen Verstand zu wege zu bringen, Rago alles zu vergifften, Megog B\u228 \'e4ume, Bluhmen, und Kr\u228 \'e4uter, V\u246 \'f6gel, Regen und Schnee zu wege zu bringen. \plain \f1\lang1033\fs24 \endash \plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 1v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (2r\endash 21r) \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24 Bericht\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 an den Exorcisten. \plain \f1\lang1033\fs24 Text, Inc.{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Ich habe allhier eine Cabalam \u8230 \'85 welche nicht allein \u8230 \'85}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \endash \plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 21v\endash 22v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 IIr\endash IIv: leer.}

