\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls16\ilvl0 \plain \f1\lang1033\fs20 Einband leicht fleckig
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls16\ilvl0 \plain \f1\lang1033\fs20 Einband an den R\u228 \'e4ndern und Ecken abgesto\u223 \'dfen
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls16\ilvl0 \plain \f1\lang1033\fs20 Buchblock leicht fleckig
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls16\ilvl0 \plain \f1\lang1033\fs20 Fortgeschrittener Tintenfra\u223 \'df
\plain\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Foliierung:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls18\ilvl0 \plain \f1\lang1033\fs20 Zeitgen\u246 \'f6ssische Tintenfoliierung \plain \f1\i\lang1033\fs20 1\endash 110\plain \f1\lang1033\fs20 .
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls18\ilvl0 \plain \f1\lang1033\fs20 Bleistiftfoliierung \plain \f1\i\lang1033\fs20 111\endash 114\plain \f1\lang1033\fs20 , wohl von {\field{\*\fldinst HYPERLINK "hida://bezper[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Robert Naumann}}\plain \f1\lang1033\fs20  im Zuge der Katalogisierung der Handschriften der Stadtbibliothek (1830er Jahre), s. u., Lit. (Naumann 1838).
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls18\ilvl0 \plain \f1\lang1033\fs20 Bleistiftfoliierung des vorderen Vorsatzblattes \plain \f1\i\lang1033\fs20 I\plain \f1\lang1033\fs20  und des letzten Blatts des Buchblocks \plain \f1\i\lang1033\fs20 115\plain \f1\lang1033\fs20  (2025).
\plain\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\line 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Wasserzeichen:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Kaum erkennbar, wohl Wappen \endash  zweikonturig (?) - bekr\u246 \'f6nt (ohne Klassifikation in WZIS).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Schriftart:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ein Schreiber, {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kurrent}}\plain \f1\lang1033\fs20 . \u220 \'dcberschriften und einzelne Textpassagen in lateinischer Schrift.
\line Derselbe Schreiber wie im Haupttext von {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. mag. 11.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 Rubrizierung und Buchschmuck:
\par \pard\li720\fi-360\jclisttab\tx0\ql\ri0\sb0\sa0\itap0 {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls15\ilvl0 \plain \f1\lang1033\fs20 Rubrizierte \u220 \'dcberschriften und Einzelbuchstaben.
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls15\ilvl0 \plain \f1\lang1033\fs20 Cadellenverzierung, z. B. auf Bl. 59r, 79r, 89r, 96r.
\plain\par {\listtext\pard\plain\f1\fs20\lang1033 \'96\tab}\ls15\ilvl0 \plain \f1\lang1033\fs20 Schriftraum durch rubrizierten Doppelrahmen begrenzt mit einer Spalte f\u252 \'fcr Anmerkungen.
\plain\par \pard\fi0\li720\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
