\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 1r\endash 12v}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 MAGIA MILITARIS. das ist Nat\u252 \'fcrliche und \u252 \'fcbernat\u252 \'fcrl. Geheimn\u252 \'fc\u223 \'dfe sich feste zu machen, die rechte Passauer Kunst, feste wieder auf zuthun, Reuter ins Feld zu machen, Kugeln abzuweisen, st\u252 \'fccke zu versagen, da\u223 \'df wenn du mit deiner Klinge deines Gegners anr\u252 \'fcherst, solche mu\u223 \'df zuspringen nebst unterschiedenen Cabbalistischen Geheimn\u252 \'fc\u223 \'dfen, vor alle Feinde, eine belagerte Stadt vor seinen Feinden zu besch\u252 \'fctzen, da\u223 \'df er solche nicht kan best\u252 \'fcrmen noch einnehmen, seine feinde in der schlacht [gestrichen: Flucht] zu \u252 \'fcberwinden, da\u223 \'df ein Kriegesherr sich in die Flucht zertrenne, eine belagerte Stadt zu infortunieren}}\plain \f1\b\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1r) Titelblatt,\plain \f1\i\lang1033\fs24  MAGIA MILITARIS. das ist Nat\u252 \'fcrliche und \u252 \'fcbernat\u252 \'fcrl. Geheimn\u252 \'fc\u223 \'dfe sich feste zu machen, die rechte Passauer Kunst, feste wieder auf zuthun, Reuter ins Feld zu machen, Kugeln abzuweisen, st\u252 \'fccke zu versagen, da\u223 \'df wenn du mit deiner Klinge deines Gegners anr\u252 \'fcherst, solche mu\u223 \'df zuspringen nebst unterschiedenen Cabbalistischen Geheimn\u252 \'fc\u223 \'dfen, vor alle Feinde, eine belagerte Stadt vor seinen Feinden zu besch\u252 \'fctzen, da\u223 \'df er solche nicht kan best\u252 \'fcrmen noch einnehmen, seine feinde in der schlacht [gestrichen: Flucht] zu \u252 \'fcberwinden, da\u223 \'df ein Kriegesherr sich in die Flucht zertrenne, eine belagerte Stadt zu infortunieren.\plain \f1\lang1033\fs24  \endash  1v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (2r\endash 12v) \u220 \'dcberschrift, \plain \f1\i\lang1033\fs24 TRACT: I. Von Feste machen Cap. I. De Experimentis Indurationis ex Magia naturali.\plain \f1\lang1033\fs24 , Text, Inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Grabe wei\u223 \'dfe Wegewart Wurzel mit Gold, Silber od. alten Gold durch aus}}\plain \f1\lang1033\fs24  \u8230 \'85 }

