\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Pappband wohl vor 1710 mit \u220 \'dcberzug aus marmoriertem Buntpapier (enger Kamm, dem Z\u228 \'e4hne fehlen, gerade. Farben: rot, blau, wei\u223 \'df, gr\u252 \'fcn, gelb). Handschriften, die in dieses oder \u228 \'e4hnliches Buntpapier gebunden sind: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. mag. 52, Cod. mag. 54, Cod. mag. 55, Cod. mag. 56, Cod. mag. 57, Cod. mag. 74, Cod. mag. 87, Cod. mag. 88, Cod. mag. 90, Cod. mag. 91, Cod. mag. 92, Cod. mag. 93, Cod. mag. 94, Cod. mag. 95, Cod. mag. 96, Cod. mag. 97, Cod. mag. 98, Cod. mag. 99, Cod. mag. 104, Cod. mag. 105, Cod. mag. 106, Cod. mag. 107, Cod. mag. 109, Cod. mag. 110, Cod. mag. 113, Cod. mag. 114, Cod. mag. 115, Cod. mag. 116, Cod. mag. 117, Cod. mag. 118, Cod. mag. 119, Cod. mag. 120, Cod. mag. 121, Cod. mag. 122, Cod. mag. 123, Cod. mag. 124, Cod. mag. 126, Cod. mag. 128, Cod. mag. 130, Cod. mag. 131, Cod. mag. 132 und Cod. mag. 135.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
